events.command:
python3 << 'PYEOF'
# Check: are there any non-Benign/LB ClinVar variants in our dataset at all?
with open('/workspace/combined_variants.tsv', 'r') as f:
    lines = f.read().strip().split('\n')

data_lines = lines[2:]

# What non-Benign ClinVar classifications exist and where?
print("=== Non-Benign/LB ClinVar variants (all, before filters) ===")
non_benign = []
for line in data_lines:
    fields = line.split('\t')
    if len(fields) < 26:
        continue
    classification = fields[25].strip()
    if classification and classification.lower() not in ('benign', 'likely benign'):
        non_benign.append({
            'chrpos': fields[0],
            'gene': fields[12],
            'seq_ont': fields[13],
            'zygosity': fields[4],
            'vaf': fields[9],
            'classification': classification,
        })

print(f"Total non-Benign/LB ClinVar variants in all samples: {len(non_benign)}")

# Check which ones would pass filters if they had VAF < 0.3
print("\n=== Non-Benign/LB variants that could pass seq/zygosity filters ===")
EXCLUDE_SEQ = ['intron_variant', '5_prime_UTR_variant', '3_prime_UTR_variant', 
               'upstream_gene_variant', 'downstream_gene_variant', 'intergenic',
               'regulatory_region_variant', 'non_coding_transcript_exon_variant',
               'TF_binding_site_variant']

for v in non_benign:
    issues = []
    if v['zygosity'] == 'Reference':
        issues.append('Reference')
    if any(t in v['seq_ont'] for t in EXCLUDE_SEQ):
        issues.append(f"Seq:{v['seq_ont']}")
    if not v['vaf']:
        issues.append('No VAF')
    else:
        try:
            vaf_val = float(v['vaf'])
            if vaf_val >= 0.3:
                issues.append(f'VAF={vaf_val:.3f} >= 0.3')
            # else VAF < 0.3 - would pass
        except ValueError:
            issues.append('Bad VAF')

    if not issues:
        print(f"  WOULD PASS: {v['chrpos']} {v['gene']} {v['seq_ont']} VAF={v['vaf']} ClinVar={v['classification']} Zyg={v['zygosity']}")
    # else filtered out

# Let's count how many would pass
would_pass = 0
for v in non_benign:
    if v['zygosity'] == 'Reference':
        continue
    if any(t in v['seq_ont'] for t in EXCLUDE_SEQ):
        continue
    if not v['vaf']:
        continue
    try:
        vaf_val = float(v['vaf'])
    except ValueError:
        continue
    if vaf_val >= 0.3:
        continue
    would_pass += 1
    print(f"  PASS: {v['chrpos']} {v['gene']} {v['seq_ont']} VAF={v['vaf']} ClinVar={v['classification']} Zyg={v['zygosity']}")

print(f"\nNon-Benign/LB passing all filters: {would_pass}")

PYEOF

